import { useEffect, useRef, useState } from "react";
import { ArrowRight, Check, ChevronRight, CircleHelp, Copy, FileVideo, Flag, Gauge, MessageSquareText, Play, Plus, RotateCcw, Sparkles, WandSparkles } from "./icons";

type RuntimeConfig = { anthropic: boolean; transcription: boolean; ffmpeg: boolean; mode: string; editor?: { engine: string; model: string; available: boolean }; brollProviders?: { pexels: boolean; pixabay: boolean } };
type BrollCandidate = { provider: "pexels" | "pixabay"; providerId: string; title: string; tags: string; previewUrl: string; downloadUrl: string; sourceUrl: string; creator: string; creatorUrl?: string; width: number; height: number; durationSeconds: number; licenseName: string; licenseUrl: string; score: number; match: { keyword: number; orientation: number; resolution: number; duration: number } };
type BrollSearchScene = { id: string; visualIntent: string; queries: string[]; candidates: BrollCandidate[]; errors: string[]; providerStatus: { pexels: string; pixabay: string } };
type BrollSearchResult = { orientation: string; scenes: BrollSearchScene[]; disclaimer: string };
type VisualEvent = { id: string; type: string; startMs?: number; endMs?: number; text?: string; subtext?: string; note?: string };
type Artifact = { name: string; url: string; kind: string; version?: number; slot?: number; title?: string; width?: number; height?: number; durationMs?: number };
type BrollEvent = { id: string; assetId: string; startMs: number; endMs: number; sourceStartMs: number };
type EditMessage = { id: string; role: "user" | "assistant"; text: string; timeMs?: number | null; rangeEndMs?: number | null; version?: number; turnId?: string; error?: boolean; createdAt?: string };
type EditTurn = { id: string; baseVersion: number; resultVersion: number; request: string; timeMs?: number | null; rangeEndMs?: number | null; status: string; error?: string; createdAt?: string; completedAt?: string };
type EditSession = { sessionId?: string | null; latestVersion: number; turnCount: number; status: string; summary?: string; messages: EditMessage[]; turns: EditTurn[] };
type Project = { id: string; status: string; goal: string; style: string; editSession?: EditSession | null; brollAssets?: { id: string; filename: string; durationMs: number; width: number; height: number; licenseConfirmed: boolean; sourceUrl?: string; licenseName?: string; licenseUrl?: string; provider?: string; sha256?: string }[]; editor?: { engine: string; model: string; version: number; phase: string; costUsd?: number; activity?: { at: string; tool?: string; message?: string }[] }; upload?: { filename: string; totalBytes: number; receivedBytes: number } | null; media?: { filename: string; durationMs: number; width: number; height: number; hasAudio: boolean; hasVideo: boolean }; music?: { filename: string; licenseConfirmed: boolean } | null; transcript?: { provider: string; text: string; segments: { startMs: number; endMs: number; text: string }[] }; plan?: { summary: string; segments: { startMs: number; endMs: number; action: string; title: string; note: string }[]; shorts: { startMs: number; endMs: number; title: string }[]; visualEvents?: VisualEvent[]; brollEvents?: BrollEvent[] }; comments?: { timeMs: number; text: string; createdAt?: string }[]; artifacts?: Artifact[]; qc?: { passed: boolean; model?: string; version?: number; main?: { durationMs: number; width: number; height: number }; subtitlesBurnedIn?: boolean; visualEventCountApplied?: number; brollEventCountApplied?: number; musicMixed?: boolean; hyperframesRendered?: boolean; audioVideoSyncChecked?: boolean; noUnexpectedBlackFrames?: boolean; visualReview?: { method: string; frames: { timeSeconds: number }[]; notes: string }; requiresHumanReview?: boolean }; error?: string; config?: RuntimeConfig };
type ProjectSummary = { id: string; status: string; goal: string; style: string; createdAt?: string; updatedAt?: string; error?: string | null; media?: { filename: string; durationMs: number; width?: number; height?: number } | null; latestVersion: number; hasTranscript: boolean; hasPlan: boolean; hasPreview: boolean; hasFinal: boolean };
type UploadProgress = { phase: "uploading" | "processing"; percent: number; receivedBytes: number; totalBytes: number } | null;
const DEFAULT_GOAL = "把这条口播剪成一条有清晰 Hook、3 个视觉强调点和结尾 CTA 的短视频。";
const CHRISTIAN_STYLE = "Christian Peverelli / Hybrid post-production";
const CHRISTIAN_RECIPE = `请按 Christian Peverelli / WeAreNoCode 在《I Fully Automated My Video Editing Using Claude Code》中展示的混合后期思路剪辑这条视频。以真实素材和转录为依据，不编造画面、台词或事实。\n\n执行步骤：\n1. 先检查视频、音频、时长、画幅和转录；保留语义完整的句子，删除停顿、口误和重录。\n2. 依据转录安排清晰 Hook、节奏紧凑的主体、关键视觉强调和结尾 CTA；所有标题与强调必须和实际台词同步。\n3. 优先使用用户上传且已确认有权使用的 B-roll；Claude 从真实可用素材中选择画面和源时间点，FFmpeg 按计划切入主片与适用的 Shorts，并保留口播原声。没有上传素材时不要伪造 B-roll。\n4. 在当前网站支持范围内生成标题卡、重点强调、字幕、配乐、主片和 5 条竖屏 Shorts，并在预览/批注后再渲染。\n5. 渲染后检查时长、音画同步、持续黑帧、字幕可读性、B-roll 执行数和导出文件；发现问题时说明并修正，不要把未完成标成通过。\n6. 如当前环境确实接入外部工具，可选用 Chrome 检索并取得有权使用的素材、HyperFrames 制作 HTML 动效、Tella 录制素材、Epidemic Sound 添加已授权音乐/音效。未接入或未授权时跳过并明确说明。\n\n视觉风格：品牌颜色、字体、转场和声音偏好优先沿用用户素材/项目设置；没有提供时保持克制、清晰、适合 YouTube 口播的编辑风格。交付前列出实际执行步骤、跳过的外部依赖和 QC 结果。`;
const API_BASE = import.meta.env.VITE_API_BASE ?? "/wayne-api";
const stageIds = ["start", "creating", "review", "rendered", "conversation"] as const;
type Stage = typeof stageIds[number];
const stageLabels = [{ id: "start", label: "准备素材" }, { id: "creating", label: "AI 制作草剪" }, { id: "review", label: "审阅与批注" }, { id: "rendered", label: "导出成片" }, { id: "conversation", label: "对话调整" }];
async function apiJson(path: string, options: RequestInit = {}) { const response = await fetch(`${API_BASE}${path}`, options); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.error || `请求失败 (${response.status})`); return data as Project; }
function userError(error: unknown, fallback: string) { const message = error instanceof Error ? error.message : String(error || ""); return /load failed|failed to fetch|networkerror/i.test(message) ? "上传连接中断，已保留已完成分块，请重新点击继续上传" : message || fallback; }
function ms(value = 0) { const total = Math.max(0, Math.round(value / 1000)); return `${String(Math.floor(total / 60)).padStart(2, "0")}:${String(total % 60).padStart(2, "0")}`; }
function visualEventType(type: VisualEvent["type"]) { return ({ title_card: "Hook 标题卡", emphasis: "重点强调", cta: "结尾 CTA" } as Record<string, string>)[type] || type; }
function stageFor(project?: Project): Stage { if (!project) return "start"; if (["chat_editing", "chat_ready"].includes(project.status) || project.editSession?.status === "running") return "conversation"; if (["rendering", "completed"].includes(project.status)) return "rendered"; if (["plan_ready", "preview_ready", "awaiting_revision"].includes(project.status) || (project.status === "failed" && project.plan)) return "review"; if (["inspecting", "transcribing", "transcript_ready", "planning", "needs_input", "failed"].includes(project.status)) return "creating"; return "start"; }
function workflowStatus(project?: Project | null) { if (!project) return "选择视频后，系统会自动开始"; if (project.error) return project.error; return ({ created: "等待上传视频", inspecting: "视频已上传，准备转录", transcribing: "正在识别口播内容", transcript_ready: "转录完成，准备生成草剪", planning: "正在生成并检查草剪", plan_ready: "草剪已准备好，请审阅", preview_ready: "草剪已准备好，请审阅", awaiting_revision: "批注已保存，可重新生成草剪或导出", rendering: "正在导出并检查成片", completed: "成片已完成，可下载", chat_editing: "Claude Code 正在基于最新版本修改", chat_ready: "新版本已生成，可以继续对话调整" } as Record<string, string>)[project.status] || "项目已保存，可以继续处理"; }
function stageHint(stage: Stage) { return ({ start: "上传素材", creating: "转录与生成", review: "播放并批注", rendered: "下载与验收", conversation: "继续修改" } as Record<Stage, string>)[stage]; }
function phaseLabel(status?: string) { return ({ created: "等待开始", inspecting: "正在检查视频", transcribing: "正在转录", transcript_ready: "转录完成", planning: "正在生成草剪", plan_ready: "草剪已完成", preview_ready: "草剪已完成", awaiting_revision: "等待你的批注", rendering: "正在导出", completed: "已完成", chat_editing: "正在修改", chat_ready: "修改完成", failed: "需要重试", needs_input: "需要配置" } as Record<string, string>)[status || ""] || "未开始"; }
function estimatedWait(project?: Project | null) { if (!project) return "通常 3–8 分钟"; if (["transcribing", "inspecting"].includes(project.status)) return "通常 1–3 分钟"; if (project.status === "planning") return "通常 4–12 分钟"; if (project.status === "rendering") return "通常 2–8 分钟"; if (project.status === "chat_editing") return "通常 2–6 分钟"; return "已完成当前耗时任务"; }
function isRecoverableError(project?: Project | null) { return Boolean(project?.error && ["needs_input", "failed"].includes(project.status)); }
function formatBytes(bytes = 0) { if (bytes < 1024 * 1024) return `${Math.max(0, Math.round(bytes / 1024))} KB`; return `${(bytes / 1024 / 1024).toFixed(1)} MB`; }
function historyStatus(item: ProjectSummary) { if (item.error) return "需要处理"; return ({ created: "待上传", inspecting: "检查中", transcribing: "转录中", transcript_ready: "待生成草剪", planning: "生成中", plan_ready: "待审阅", preview_ready: "待审阅", awaiting_revision: "等待修订", rendering: "导出中", completed: "已完成", chat_editing: "修改中", chat_ready: "有新版本", failed: "可恢复" } as Record<string, string>)[item.status] || "已保存"; }
function relativeDate(value?: string) { if (!value) return "刚刚"; const delta = Math.max(0, Date.now() - new Date(value).getTime()); const minutes = Math.floor(delta / 60000); if (minutes < 1) return "刚刚"; if (minutes < 60) return `${minutes} 分钟前`; const hours = Math.floor(minutes / 60); if (hours < 24) return `${hours} 小时前`; return `${Math.floor(hours / 24)} 天前`; }

export default function App() {
  const [project, setProject] = useState<Project | null>(null); const [runtime, setRuntime] = useState<RuntimeConfig | null>(null); const [history, setHistory] = useState<ProjectSummary[]>([]); const [showHistory, setShowHistory] = useState(false); const [showHelp, setShowHelp] = useState(false); const [stage, setStage] = useState<Stage>("start"); const [selectedFile, setSelectedFile] = useState<File | null>(null); const [musicFile, setMusicFile] = useState<File | null>(null); const [brollFiles, setBrollFiles] = useState<File[]>([]); const [licenseAccepted, setLicenseAccepted] = useState(false); const [goal, setGoal] = useState(DEFAULT_GOAL); const [style, setStyle] = useState("Wayne / clean creator"); const [comment, setComment] = useState(""); const [commentTime, setCommentTime] = useState("0"); const [chatDraft, setChatDraft] = useState(""); const [chatTime, setChatTime] = useState(""); const [chatRangeEnd, setChatRangeEnd] = useState(""); const [viewVersion, setViewVersion] = useState<number | null>(null); const [busy, setBusy] = useState(false); const [message, setMessage] = useState(""); const [recipeNotice, setRecipeNotice] = useState(""); const [uploadProgress, setUploadProgress] = useState<UploadProgress>(null); const [brollSearchText, setBrollSearchText] = useState(""); const [brollOrientation, setBrollOrientation] = useState("landscape"); const [brollSearchResult, setBrollSearchResult] = useState<BrollSearchResult | null>(null); const [brollSearchBusy, setBrollSearchBusy] = useState(false); const [brollSearchError, setBrollSearchError] = useState(""); const conversationVideoRef = useRef<HTMLVideoElement | null>(null); const sourceRef = useRef<EventSource | null>(null); const projectId = project?.id; const config = project?.config || runtime;
  useEffect(() => { void fetch(`${API_BASE}/api/config`).then((response) => response.json()).then(setRuntime).catch(() => undefined); void fetch(`${API_BASE}/api/projects?limit=20`).then((response) => response.json()).then((data) => setHistory(data.projects || [])).catch(() => undefined); const saved = localStorage.getItem("wayne-project-id"); if (saved) void apiJson(`/api/projects/${saved}`).then((item) => { setProject(item); setStage(stageFor(item)); }).catch(() => localStorage.removeItem("wayne-project-id")); return () => sourceRef.current?.close(); }, []);
  useEffect(() => { if (!projectId) return; localStorage.setItem("wayne-project-id", projectId); sourceRef.current?.close(); const source = new EventSource(`${API_BASE}/api/projects/${projectId}/events`); source.onmessage = (event) => { const payload = JSON.parse(event.data); if (payload.project) { setProject(payload.project); setStage(stageFor(payload.project)); } else void apiJson(`/api/projects/${projectId}`).then((item) => { setProject(item); setStage(stageFor(item)); }); }; sourceRef.current = source; return () => source.close(); }, [projectId]);
  async function refreshHistory() { const response = await fetch(`${API_BASE}/api/projects?limit=20`); const data = await response.json(); setHistory(data.projects || []); }
  async function openHistory(id: string) { setBusy(true); try { const next = await apiJson(`/api/projects/${id}`); setProject(next); setStage(stageFor(next)); setShowHistory(false); localStorage.setItem("wayne-project-id", id); } finally { setBusy(false); } }
  const currentIndex = stageIds.indexOf(stage); const progress = Math.round((currentIndex / (stageIds.length - 1)) * 100); const artifactUrl = (url: string) => `${API_BASE}${url}`; const latestVersion = project?.editSession?.latestVersion || project?.editor?.version || project?.qc?.version || 1; const displayVersion = viewVersion || latestVersion; const latestArtifacts = (project?.artifacts || []).filter((artifact) => (artifact.version || 1) === latestVersion); const displayArtifacts = (project?.artifacts || []).filter((artifact) => (artifact.version || 1) === displayVersion); const previewArtifact = [...latestArtifacts].reverse().find((artifact) => artifact.kind === "preview"); const mainArtifact = [...latestArtifacts].reverse().find((artifact) => artifact.kind === "video") || [...(project?.artifacts || [])].reverse().find((artifact) => artifact.kind === "video"); const conversationArtifact = [...displayArtifacts].reverse().find((artifact) => artifact.kind === "preview") || [...displayArtifacts].reverse().find((artifact) => artifact.kind === "video") || mainArtifact; const versions = [...new Set((project?.artifacts || []).map((artifact) => artifact.version || 1))].sort((a, b) => a - b);
  async function uploadInChunks(id: string, file: File) { const chunkSize = 8 * 1024 * 1024; setUploadProgress({ phase: "uploading", percent: 0, receivedBytes: 0, totalBytes: file.size }); for (let offset = 0; offset < file.size; offset += chunkSize) { const end = Math.min(file.size, offset + chunkSize); let lastError: unknown; for (let attempt = 0; attempt < 3; attempt += 1) { try { await apiJson(`/api/projects/${id}/input/chunk`, { method: "POST", headers: { "Content-Type": "application/octet-stream", "X-Upload-Length": String(end - offset), "X-Upload-Offset": String(offset), "X-Upload-Total": String(file.size), "X-Upload-Filename": encodeURIComponent(file.name), "X-Upload-Filename-Encoding": "uri" }, body: file.slice(offset, end) }); lastError = undefined; break; } catch (error) { lastError = error; if (attempt < 2) await new Promise((resolve) => setTimeout(resolve, 500 * (attempt + 1))); } } if (lastError) throw lastError; const receivedBytes = end; setUploadProgress({ phase: "uploading", percent: Math.round((receivedBytes / file.size) * 100), receivedBytes, totalBytes: file.size }); setMessage(`正在上传素材 ${Math.round((end / file.size) * 100)}%`); } setUploadProgress({ phase: "processing", percent: 100, receivedBytes: file.size, totalBytes: file.size }); return apiJson(`/api/projects/${id}/input/complete`, { method: "POST" }); }
  async function uploadMusic(id: string) { if (!musicFile) return; if (!licenseAccepted) throw new Error("请确认你拥有所选音乐和 B-roll 素材的使用许可"); const form = new FormData(); form.append("file", musicFile); form.append("licenseConfirmed", "true"); const next = await apiJson(`/api/projects/${id}/music`, { method: "POST", headers: { "X-Music-Filename": encodeURIComponent(musicFile.name) }, body: form }); setProject(next); }
  async function uploadBroll(id: string, file: File) { if (!licenseAccepted) throw new Error("请确认你拥有所选音乐和 B-roll 素材的使用许可"); const form = new FormData(); form.append("file", file); form.append("licenseConfirmed", "true"); const next = await apiJson(`/api/projects/${id}/broll`, { method: "POST", headers: { "X-Broll-Filename": encodeURIComponent(file.name) }, body: form }); setProject(next); }
  async function searchOnlineBroll() { if (!projectId) return; setBrollSearchBusy(true); setBrollSearchError(""); try { const response = await fetch(`${API_BASE}/api/projects/${projectId}/broll/search`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ text: brollSearchText.trim() || project?.transcript?.text || project?.goal || "", orientation: brollOrientation }) }); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.error || `B-roll 搜索失败 (${response.status})`); setBrollSearchResult(data as BrollSearchResult); } catch (error) { setBrollSearchError(error instanceof Error ? error.message : "B-roll 搜索失败"); } finally { setBrollSearchBusy(false); } }
  async function advanceProject(id: string) { return apiJson(`/api/projects/${id}/advance`, { method: "POST", headers: { "Content-Type": "application/json" }, body: "{}" }); }
  async function createDraft(id: string) { let next = await advanceProject(id); setProject(next); setStage(stageFor(next)); if (next.status === "transcript_ready") { next = await advanceProject(id); setProject(next); setStage(stageFor(next)); } }
  async function startProject(file = selectedFile) { if (!file) return; setSelectedFile(file); if ((musicFile || brollFiles.length) && !licenseAccepted) { setMessage("请确认你拥有所选配乐和 B-roll 素材的使用许可"); return; } setBusy(true); setMessage(""); let activeId = project?.id; try { const created = activeId && !project?.media ? project : await apiJson("/api/projects", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ goal, style }) }); if (!created) throw new Error("无法创建项目"); activeId = created.id; setProject(created); setStage("start"); for (const item of brollFiles) await uploadBroll(created.id, item); if (musicFile) await uploadMusic(created.id); const uploaded = await uploadInChunks(created.id, file); setProject(uploaded); setStage("creating"); await createDraft(uploaded.id); await refreshHistory(); } catch (error) { if (activeId) { try { const current = await apiJson(`/api/projects/${activeId}`); setProject(current); setStage(stageFor(current)); } catch { /* keep the original upload error visible */ } } setMessage(userError(error, "上传失败，请重试")); } finally { setBusy(false); setUploadProgress(null); } }
  async function continueWorkflow() { if (!projectId) return; setBusy(true); setMessage(""); try { await createDraft(projectId); } catch (error) { setMessage(userError(error, "处理失败，项目已保留，可以重试")); const current = await apiJson(`/api/projects/${projectId}`).catch(() => undefined); if (current) { setProject(current); setStage(stageFor(current)); } } finally { setBusy(false); } }
  async function replanVisuals() { if (!projectId) return; setBusy(true); setMessage(""); try { const next = await apiJson(`/api/projects/${projectId}/replan`, { method: "POST" }); setProject(next); setStage("review"); } catch (error) { setMessage(userError(error, "视觉剪辑计划生成失败")); const current = await apiJson(`/api/projects/${projectId}`).catch(() => undefined); if (current) setProject(current); } finally { setBusy(false); } }
  async function advance(id = projectId) { if (!id) return; setBusy(true); setMessage(""); try { const next = await advanceProject(id); setProject(next); setStage(stageFor(next)); } catch (error) { setMessage(error instanceof Error ? error.message : "服务请求失败"); } finally { setBusy(false); } }
  async function addComment() { if (!projectId || !comment.trim()) return; setBusy(true); try { const next = await apiJson(`/api/projects/${projectId}/comments`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ text: comment, timeMs: Math.max(0, Number(commentTime) * 1000) }) }); setProject(next); setComment(""); setCommentTime("0"); setStage("review"); } catch (error) { setMessage(error instanceof Error ? error.message : "批注保存失败"); } finally { setBusy(false); } }
  async function render() { if (!projectId) return; setBusy(true); setMessage(""); try { const next = await apiJson(`/api/projects/${projectId}/render`, { method: "POST" }); setProject(next); setStage("rendered"); } catch (error) { setMessage(error instanceof Error ? error.message : "渲染失败"); } finally { setBusy(false); } }
  async function sendChatMessage(text = chatDraft) { if (!projectId || !text.trim()) return; setBusy(true); setMessage(""); try { const next = await apiJson(`/api/projects/${projectId}/chat/messages`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ text: text.trim(), timeMs: chatTime ? Number(chatTime) * 1000 : null, rangeEndMs: chatRangeEnd ? Number(chatRangeEnd) * 1000 : null }) }); setProject(next); setStage("conversation"); setChatDraft(""); setChatTime(""); setChatRangeEnd(""); } catch (error) { setMessage(userError(error, "对话修改请求失败")); } finally { setBusy(false); } }
  function applyChristianRecipe() { setGoal(CHRISTIAN_RECIPE); setStyle(CHRISTIAN_STYLE); setRecipeNotice("混合后期配方已载入；选择视频后即可开始执行。"); }
  async function copyChristianRecipe() { try { await navigator.clipboard.writeText(CHRISTIAN_RECIPE); setRecipeNotice("完整剪辑指令已复制到剪贴板。"); } catch { setRecipeNotice("浏览器未允许剪贴板访问；请先点击“载入配方”，再从剪辑目标框复制。"); } }
  function reset() { sourceRef.current?.close(); localStorage.removeItem("wayne-project-id"); setProject(null); setSelectedFile(null); setMusicFile(null); setBrollFiles([]); setLicenseAccepted(false); setGoal(DEFAULT_GOAL); setStage("start"); setMessage(""); setCommentTime("0"); }
  const segments = project?.transcript?.segments || []; const cuts = project?.plan?.segments || []; const shorts = project?.plan?.shorts || []; const visualEvents = project?.plan?.visualEvents || []; const brollEvents = project?.plan?.brollEvents || [];
  return <main className="app-shell">
    <header className="topbar">
      <div className="brand-lockup"><div className="brand-mark"><span /><span /><span /></div><div><p className="eyebrow">CUTLINE / CASE 01</p><h1>Wayne 视频剪辑</h1></div></div>
      <div className="topbar-actions"><span className={`connection-pill ${config?.mode === "configured" ? "ready" : "missing"}`}>{config?.mode === "configured" ? "服务已就绪" : config?.mode === "partial" ? "服务部分就绪" : "服务待配置"}</span><button className="topbar-link" type="button" onClick={() => { setShowHistory(true); void refreshHistory(); }}>项目历史 <span>{history.length}</span></button><button className="icon-button" aria-label="帮助" title="上传口播视频，审阅 AI 草剪，再确认导出。" onClick={() => setShowHelp(true)}><CircleHelp size={18} /></button></div>
    </header>

    <section className="workflow-intro">
      <div className="hero-copy"><p className="case-label"><Sparkles size={14} /> 一条口播，剪成可发布视频</p><h2>先看草剪，<em>满意再导出。</em></h2><p>上传视频后，AI 会自动转录并制作预览。你可以直接批注，再确认生成成片。</p>
        <div className="hero-actions">{stage === "start" ? <button className="primary-button" onClick={() => document.getElementById("video-file")?.click()}><FileVideo size={17} /> 选择视频</button> : null}{project ? <button className="text-button" onClick={reset}><RotateCcw size={15} /> 新建项目</button> : null}{!project && history.length ? <button className="text-button" onClick={() => { setShowHistory(true); void refreshHistory(); }}>从项目历史恢复 <ArrowRight size={15} /></button> : null}</div>
      </div>
    </section>

    <section className="workspace" id="workspace">
      <div className="workspace-heading"><div><p className="eyebrow">VIDEO WORKFLOW</p><h2>本次剪辑</h2></div><div className="run-state"><span className="status-dot" /> {busy && message ? message : workflowStatus(project)}</div></div>
      {config && config.mode !== "configured" && <div className="config-guide"><div className="config-guide-icon"><CircleHelp size={18} /></div><div><strong>{config.mode === "demo" ? "先完成服务配置，再开始真实剪辑" : "部分服务还未配置"}</strong><p>{config.anthropic ? "Claude 已就绪。" : "需要配置 ANTHROPIC_API_KEY 才能生成草剪。"} {config.transcription ? "转录服务已就绪。" : "还需要配置火山引擎或腾讯云转录。"}</p></div><details><summary>查看配置清单</summary><ul><li className={config.anthropic ? "ready" : "missing"}>{config.anthropic ? "✓" : "○"} Claude / Anthropic API</li><li className={config.transcription ? "ready" : "missing"}>{config.transcription ? "✓" : "○"} 视频转录服务</li><li className={config.editor?.available ? "ready" : "missing"}>{config.editor?.available ? "✓" : "○"} Claude Code 与媒体隔离工具</li></ul><small>编辑服务读取 portal/.env，修改后请重启 API 服务。</small></details></div>}
      <nav className="stage-rail" aria-label="剪辑流程">{stageLabels.map((item, index) => <button key={item.id} type="button" className={`stage-step ${item.id === stage ? "active" : ""} ${index < currentIndex ? "complete" : ""}`} onClick={() => index <= currentIndex && setStage(item.id as Stage)} aria-current={item.id === stage ? "step" : undefined}><span className="step-number">{index < currentIndex ? <Check size={14} /> : String(index + 1).padStart(2, "0")}</span><span><strong>{item.label}</strong><small>{stageHint(item.id as Stage)}</small></span></button>)}</nav>

      <div className="workspace-grid"><section className="main-panel">
        {stage === "start" && <>
          <div className="panel-header"><div><p className="eyebrow">01 / 准备素材</p><h3>上传一条口播视频</h3></div><span className="soft-tag">约 60–90 秒效果最佳</span></div>
          <div className="drop-zone" onClick={() => document.getElementById("video-file")?.click()} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") document.getElementById("video-file")?.click(); }} role="button" tabIndex={0}><div className="drop-icon"><FileVideo size={24} /></div><input id="video-file" type="file" accept="video/mp4,video/quicktime,video/*" hidden onChange={(event) => { const file = event.target.files?.[0]; if (file) void startProject(file); }} /><strong>{selectedFile ? selectedFile.name : project?.media ? `${project.media.filename} 已上传` : "选择一条口播视频"}</strong><span>{selectedFile ? `${(selectedFile.size / 1024 / 1024).toFixed(1)} MB · 已开始上传和制作` : project?.media ? `${ms(project.media.durationMs)} · ${project.media.width} × ${project.media.height}` : "MP4 / MOV · 视频保存在本机服务端"}</span><button type="button" className="secondary-button" onClick={(event) => { event.stopPropagation(); document.getElementById("video-file")?.click(); }}><Plus size={16} /> {selectedFile ? "更换视频" : "选择文件"}</button></div>
          <details className="advanced-options"><summary>高级选项 <span>风格、配乐、补充素材</span></summary>
            <div className="case-recipe-card"><div><p className="eyebrow">B EVIDENCE · 2026.10.04</p><strong>Christian Peverelli / WeAreNoCode</strong><span>混合后期：转录、动效、B-roll、声音与最终 QC</span></div><div className="recipe-actions"><button type="button" className="secondary-button" onClick={applyChristianRecipe}><WandSparkles size={15} /> 载入完整配方</button><button type="button" className="text-button" onClick={() => void copyChristianRecipe()}><Copy size={15} /> 复制完整指令</button></div>{recipeNotice && <p className="recipe-notice" role="status">{recipeNotice}</p>}<small>HyperFrames 动效已接入；其他外部工具与素材需要单独连接或授权。</small><a href="https://www.youtube.com/watch?v=HzXD4GVqXwM" target="_blank" rel="noreferrer">查看原始 walkthrough <ArrowRight size={13} /></a></div>
            <div className="music-upload-card"><label htmlFor="music-file">可选配乐 <small>{musicFile?.name || project?.music?.filename || "MP3 / WAV / M4A · 最多 50 MB"}</small></label><input id="music-file" type="file" accept="audio/mpeg,audio/wav,audio/mp4,audio/aac,audio/ogg,audio/flac,.mp3,.wav,.m4a,.aac,.ogg,.flac" onChange={(event) => setMusicFile(event.target.files?.[0] || null)} /><label className="license-check"><input type="checkbox" checked={licenseAccepted} onChange={(event) => setLicenseAccepted(event.target.checked)} /><span>我确认拥有所选配乐和 B-roll 素材用于本次视频的使用许可</span></label><small className="music-note">未添加配乐时，成片保留视频原声。</small></div>
            <div className="broll-upload-card"><label htmlFor="broll-file">可选 B-roll 视频 <small>{brollFiles.length ? `已选 ${brollFiles.length} 个素材` : `${project?.brollAssets?.length || 0} 个项目素材 · MP4 / MOV / WebM`}</small></label><input id="broll-file" type="file" accept="video/mp4,video/quicktime,video/webm,.mp4,.mov,.m4v,.webm" multiple onChange={(event) => setBrollFiles(Array.from(event.target.files || []))} /><small>Claude 可按内容挑选已上传素材并安排插入时间。</small>{project?.brollAssets?.length ? <ul>{project.brollAssets.map((asset) => <li key={asset.id}>{asset.filename} · {ms(asset.durationMs)} · {asset.width} × {asset.height}</li>)}</ul> : null}</div>
            <div className="form-grid"><label><span>剪辑目标</span><textarea value={goal} onChange={(event) => setGoal(event.target.value)} /></label><label><span>视觉风格</span><select value={style} onChange={(event) => setStyle(event.target.value)}><option>Wayne / clean creator</option><option>Warm knowledge</option><option>Vibe coding dark</option><option>{CHRISTIAN_STYLE}</option></select></label></div>
          </details>
          {!project && <div className="empty-start-note"><div className="empty-start-icon"><FileVideo size={18} /></div><div><strong>从一条视频开始</strong><p>建议使用 60–90 秒、声音清晰的口播。上传后会自动保存，处理中可以离开页面。</p></div></div>}
          {uploadProgress && <div className="upload-progress-card" aria-live="polite"><div className="upload-progress-heading"><strong>{uploadProgress.phase === "processing" ? "视频已上传，正在读取媒体信息…" : "正在上传视频"}</strong><span>{uploadProgress.percent}%</span></div><div className="upload-progress-track"><span style={{ width: `${uploadProgress.percent}%` }} /></div><small>{formatBytes(uploadProgress.receivedBytes)} / {formatBytes(uploadProgress.totalBytes)} · 上传中断时会自动从已完成分块继续</small></div>}
          {message && <div className="api-alert"><strong>{message}</strong><small>上传会自动续传已完成的文件分块；项目和已生成结果会保留。</small></div>}
          {project?.media && <button type="button" className="continue-button" disabled={busy || ["transcribing", "planning", "rendering"].includes(project.status)} onClick={() => project.plan ? setStage("review") : void continueWorkflow()}>{project.plan ? "返回草剪审阅" : "继续制作草剪"} <ChevronRight size={18} /></button>}
        </>}

        {stage === "creating" && <>
          <div className="panel-header"><div><p className="eyebrow">02 / AI 制作草剪</p><h3>{project?.status === "transcript_ready" ? "口播已转录，准备生成草剪" : project?.status === "transcribing" ? "正在识别口播内容" : project?.status === "planning" ? "正在生成并检查草剪" : "正在准备视频"}</h3></div><span className="soft-tag orange"><WandSparkles size={14} /> 自动处理</span></div>
          <div className={`creation-progress ${isRecoverableError(project) ? "is-error" : ""}`} aria-live="polite"><span className="creation-pulse" /><div className="creation-progress-copy"><div className="progress-title-row"><strong>{busy && message ? message : workflowStatus(project)}</strong><span className="progress-eta">{estimatedWait(project)}</span></div><p>{project?.editor?.activity?.at(-1)?.message || (isRecoverableError(project) ? "现场已保存。你可以从上次完成的阶段继续，不需要重新上传视频。" : "转录完成后会自动生成可播放草剪。完成后请在同一页面审阅视频并决定是否导出。")}</p><div className="phase-checklist"><span className={project?.transcript ? "done" : project?.status === "transcribing" ? "current" : ""}><i>{project?.transcript ? "✓" : "1"}</i> 读取并转录</span><span className={project?.plan ? "done" : project?.status === "planning" ? "current" : ""}><i>{project?.plan ? "✓" : "2"}</i> 生成草剪</span><span className={project?.plan && previewArtifact ? "done" : ""}><i>{project?.plan && previewArtifact ? "✓" : "3"}</i> 检查预览</span></div></div></div>
          {project?.transcript && <details className="review-details"><summary>查看逐句转录</summary><div className="transcript-list">{segments.map((segment, index) => <p key={`${segment.startMs}-${index}`}><time>{ms(segment.startMs)}</time><span>{segment.text || "（无文本）"}</span></p>)}</div></details>}
          {project?.error && <div className={`api-alert ${isRecoverableError(project) ? "recoverable" : ""}`}><div><strong>{project.error}</strong><small>{isRecoverableError(project) ? "已保留视频、转录和工作区，可以安全重试。" : "请处理后再继续，已完成步骤仍会保留。"}</small></div><span className="alert-label">{isRecoverableError(project) ? "可恢复" : "需要处理"}</span></div>}
          {(project?.status === "inspecting" || project?.status === "transcript_ready" || project?.status === "needs_input" || project?.status === "failed") && <button type="button" className="continue-button" disabled={busy} onClick={() => void continueWorkflow()}>{project?.transcript ? (project?.error ? "从这里继续生成" : "继续生成草剪") : project.status === "inspecting" ? "开始转录并制作草剪" : "重试视频转录"} <ChevronRight size={18} /></button>}
        </>}

        {stage === "review" && <>
          <div className="panel-header"><div><p className="eyebrow">03 / 审阅与批注</p><h3>先看草剪，满意后再导出</h3></div><span className="soft-tag success"><Play size={14} /> {project?.comments?.length ? `${project.comments.length} 条修改意见` : "草剪已就绪"}</span></div>
          <div className="review-guide" aria-label="审阅步骤"><span><b>01</b>完整播放</span><span><b>02</b>在时间点批注</span><span><b>03</b>确认后导出</span></div>
          {previewArtifact ? <><video className="source-player review-player" controls playsInline src={artifactUrl(previewArtifact.url)} /><p className="preview-notes">这是 AI 生成的草剪。可以直接添加时间点和修改意见，再确认生成正式成片。</p></> : <div className="api-alert"><strong>{project?.error || "暂时没有可播放的草剪。"}</strong><button type="button" className="secondary-button" disabled={busy} onClick={() => void replanVisuals()}>重新生成草剪</button></div>}
          <div className="review-plan"><span>剪辑方案</span><strong>{project?.plan?.summary || "AI 已生成剪辑方案。"}</strong><details className="review-details"><summary>查看转录与剪辑细节</summary><div className="transcript-list">{segments.map((segment, index) => <p key={`${segment.startMs}-${index}`}><time>{ms(segment.startMs)}</time><span>{segment.text || "（无文本）"}</span></p>)}</div>{cuts.length ? <div className="cut-list">{cuts.map((cut, index) => <div className={`cut-row ${cut.action === "tighten" ? "tighten" : cut.action === "remove" ? "remove" : ""}`} key={`${cut.startMs}-${index}`}><span className="cut-time">{ms(cut.startMs)}–{ms(cut.endMs)}</span><span className="cut-kind">{cut.action === "keep" ? "保留" : cut.action === "tighten" ? "收紧" : "删除"}</span><div><strong>{cut.title}</strong><p>{cut.note}</p></div></div>)}</div> : null}{visualEvents.length ? <div className="visual-plan-list">{visualEvents.map((event) => <div className={`visual-event visual-event-${event.type}`} key={event.id}><span className="cut-time">{ms(event.startMs)}–{ms(event.endMs)}</span><span className="visual-event-type">{visualEventType(event.type)}</span><div><strong>{event.text}</strong>{event.subtext && <p>{event.subtext}</p>}</div></div>)}</div> : null}</details></div>
          <div className="review-timeline"><div className="timeline-bar" /><div className="timeline-labels"><span>00:00</span><span>{ms(project?.media?.durationMs ? project.media.durationMs / 3 : 20000)}</span><span>{ms(project?.media?.durationMs ? project.media.durationMs * 2 / 3 : 40000)}</span><span>{ms(project?.media?.durationMs || 60000)}</span></div></div>
          <div className="comment-box"><input className="comment-time" type="number" min="0" step="0.1" value={commentTime} onChange={(event) => setCommentTime(event.target.value)} aria-label="批注时间（秒）" /><input value={comment} onChange={(event) => setComment(event.target.value)} onKeyDown={(event) => event.key === "Enter" && void addComment()} placeholder="写下要修改的地方，例如：00:12 的标题提前一点出现" aria-label="修改意见" /><button type="button" aria-label="添加批注" disabled={!comment.trim() || busy} onClick={() => void addComment()}><Plus size={17} /></button></div>
          {project?.comments?.length ? <div className="comment-list">{project.comments.map((item, index) => <p key={`${item.createdAt || index}`}><span>{ms(item.timeMs)}</span>{item.text}<Check size={15} /></p>)}</div> : null}
          <details className="review-advanced"><summary>可选：搜索在线 B-roll 素材</summary><div className="broll-search-card"><div className="broll-search-heading"><div><p className="eyebrow">ONLINE STOCK SEARCH</p><h4>按文案找 B-roll</h4></div><span>{config?.brollProviders?.pexels ? "Pexels" : "Pexels 未配置"} · {config?.brollProviders?.pixabay ? "Pixabay" : "Pixabay 未配置"}</span></div><label className="broll-search-copy"><span>搜索依据：编辑后可改为更具体的画面描述</span><textarea value={brollSearchText} onChange={(event) => setBrollSearchText(event.target.value)} placeholder={project?.transcript?.text?.slice(0, 280) || project?.plan?.summary || "例如：夜晚独自工作的人，在笔记本电脑前敲键盘"} /></label><div className="broll-search-controls"><label>目标画幅<select value={brollOrientation} onChange={(event) => setBrollOrientation(event.target.value)}><option value="landscape">横屏</option><option value="portrait">竖屏</option><option value="square">方形</option></select></label><button className="secondary-button" disabled={brollSearchBusy || (!config?.brollProviders?.pexels && !config?.brollProviders?.pixabay)} onClick={() => void searchOnlineBroll()}><Sparkles size={15} /> {brollSearchBusy ? "正在生成分镜并搜索…" : "AI 分镜 + 在线搜索"}</button></div><small className="broll-search-note">点击会消耗一次 Claude 请求；缓存未命中时最多发出 12 次素材 API 查询。每次最多分析 3 个画面意图，结果按关键词、画幅、分辨率和片长启发式排序，不代表视觉模型验证。查询缓存 24 小时；使用前请查看素材来源及具体授权。</small>{!config?.brollProviders?.pexels && !config?.brollProviders?.pixabay ? <div className="api-alert"><strong>尚未配置视频素材 API Key。</strong><small>在服务端 portal/.env 配置 PEXELS_API_KEY 和/或 PIXABAY_API_KEY 后重启 API。当前不会发送外部搜索请求。</small></div> : null}{brollSearchError ? <div className="api-alert"><strong>{brollSearchError}</strong></div> : null}{brollSearchResult ? <><p className="broll-search-disclaimer">{brollSearchResult.disclaimer}</p>{brollSearchResult.scenes.map((scene) => <div className="broll-search-scene" key={scene.id}><div className="broll-search-scene-heading"><div><strong>{scene.visualIntent}</strong><small>搜索词：{scene.queries.join(" · ")}</small></div><span>{scene.candidates.length} 个候选</span></div>{scene.errors.length ? <small className="broll-search-error">{[...new Set(scene.errors)].join("；")}</small> : null}<div className="broll-candidate-grid">{scene.candidates.map((candidate) => <article className="broll-candidate" key={`${candidate.provider}-${candidate.providerId}`}><video controls preload="none" playsInline poster={candidate.previewUrl} src={candidate.downloadUrl} /><div className="broll-candidate-meta"><span className="score-pill">预排序 {candidate.score}</span><span>{candidate.provider === "pexels" ? "Pexels" : "Pixabay"} · {candidate.durationSeconds}s · {candidate.width}×{candidate.height}</span></div><strong>{candidate.title || candidate.tags}</strong><small>{candidate.creator ? `作者：${candidate.creator}` : ""} · 关键词 {candidate.match.keyword} · 画幅 {candidate.match.orientation} · 清晰度 {candidate.match.resolution}</small><div className="broll-candidate-links"><a href={candidate.sourceUrl} target="_blank" rel="noreferrer">来源与授权</a><a href={candidate.downloadUrl} target="_blank" rel="noreferrer">打开视频 / 下载</a><a href={candidate.licenseUrl} target="_blank" rel="noreferrer">{candidate.licenseName}</a></div></article>)}</div></div>)}</> : null}</div></details>
          {message && <div className="api-alert"><strong>{message}</strong></div>}
          {project?.error && <div className="api-alert"><strong>{project.error}</strong></div>}
          <button type="button" className="secondary-button revise-button" disabled={busy || !project?.comments?.length || !previewArtifact} onClick={() => void advance()}>{busy ? "正在生成修订版草剪…" : "根据批注生成修订版草剪"}</button>
          <button type="button" className="continue-button" disabled={busy || project?.status === "completed" || !project?.plan || !previewArtifact} onClick={() => void render()}>{busy ? "正在导出并检查成片…" : project?.status === "completed" ? "成片已完成" : "确认草剪并导出成片"} <ChevronRight size={18} /></button>
        </>}

        {stage === "rendered" && <>
          <div className="panel-header"><div><p className="eyebrow">04 / 导出成片</p><h3>{project?.qc?.passed ? "成片已导出并检查" : project?.status === "rendering" ? "正在导出并检查成片" : "导出暂未完成"}</h3></div><span className={`soft-tag ${project?.qc?.passed ? "success" : "orange"}`}><Check size={14} /> {project?.qc?.passed ? "质量检查通过" : "处理中"}</span></div>
          {project?.status === "rendering" && <div className="creation-progress" aria-live="polite"><span className="creation-pulse" /><div><strong>{project?.editor?.activity?.at(-1)?.tool || "正在导出成片"}</strong><p>{project?.editor?.activity?.at(-1)?.message || "正在按剪辑方案导出并检查文件。"}</p></div></div>}
          {mainArtifact && <video className="source-player" controls playsInline src={artifactUrl(mainArtifact.url)} />}
          {project?.error && <div className="api-alert"><strong>{project.error}</strong><small>草剪和项目记录已保留，可以返回审阅后重试。</small></div>}
          <div className="delivery-summary"><div className="delivery-video"><div className="mini-play"><Play size={18} fill="currentColor" /></div><div><strong>{mainArtifact?.name || "等待成片生成"}</strong><span>{project?.qc?.main ? `${ms(project.qc.main.durationMs)} · ${project.qc.main.width} × ${project.qc.main.height}` : ""}</span></div></div>{project?.qc && <div className="delivery-proof"><span>版本 v{project.qc.version || 1}</span><span>Claude Code · {project.qc.model}</span><span>{project.qc.visualReview?.frames.length || 0} 张成片画面已检查</span><span>{project.qc.audioVideoSyncChecked ? "音画同步已检查" : "音画同步待检查"}</span><span>{project.qc.noUnexpectedBlackFrames ? "黑帧检查通过" : "黑帧检查未通过或未完成"}</span><span>请完整观看成片并确认字幕与内容</span><p>{project.qc.visualReview?.notes}</p></div>}<div className="artifact-links">{latestArtifacts.map((artifact) => <a key={artifact.name} href={artifactUrl(artifact.url)}>{artifact.name} <ArrowRight size={14} /> <span>下载</span></a>)}</div></div>
          <div className="shorts-grid">{shorts.map((item, index) => { const artifact = latestArtifacts.find((entry) => entry.kind === "short" && entry.slot === index + 1) || latestArtifacts.find((entry) => entry.name === `short-${String(index + 1).padStart(2, "0")}.mp4`); return <div className="short-card orange" key={item.title}><div className="short-thumb"><span>{item.title}</span><Play size={17} fill="currentColor" /></div><strong>{item.title}</strong><small>{ms(item.endMs - item.startMs)} · 9:16 · {artifact ? <a href={artifactUrl(artifact.url)}>下载</a> : "等待产物"}</small></div>; })}</div><button type="button" className="continue-button" disabled={!project?.qc?.passed || busy} onClick={() => setStage("conversation")}><MessageSquareText size={17} /> 继续对话调整最新版本 <ChevronRight size={18} /></button><button type="button" className="text-button" onClick={reset}><RotateCcw size={17} /> 开始剪下一条视频</button>
        </>}

        {stage === "conversation" && <>
          <div className="conversation-layout">
            <section className="conversation-media-panel">
              <div className="panel-header"><div><p className="eyebrow">05 / 对话调整</p><h3>继续修改最新版本</h3></div><span className={`soft-tag ${project?.status === "chat_editing" ? "orange" : "success"}`}>{project?.status === "chat_editing" ? "正在修改" : `当前 v${latestVersion}`}</span></div>
              {conversationArtifact ? <video ref={conversationVideoRef} className="source-player conversation-player" controls playsInline src={artifactUrl(conversationArtifact.url)} /> : <div className="api-alert"><strong>暂无可播放的版本。</strong></div>}
              <div className="conversation-version-bar"><label>查看版本<select value={displayVersion} onChange={(event) => setViewVersion(Number(event.target.value))}>{versions.map((version) => <option key={version} value={version}>v{version}{version === latestVersion ? " · 最新" : ""}</option>)}</select></label>{displayVersion !== latestVersion ? <button type="button" className="text-button" onClick={() => setViewVersion(null)}>回到最新版本</button> : null}<span>下一轮修改始终基于 v{latestVersion}</span></div>
              <div className="conversation-timeline"><div className="timeline-bar" /><div className="timeline-labels"><span>00:00</span><span>{ms(project?.media?.durationMs ? project.media.durationMs / 3 : 20000)}</span><span>{ms(project?.media?.durationMs ? project.media.durationMs * 2 / 3 : 40000)}</span><span>{ms(project?.media?.durationMs || 60000)}</span></div></div>
              <div className="conversation-diff"><span>最新版本 v{latestVersion}</span><strong>{project?.qc?.visualReview?.notes || "保持当前剪辑风格，按对话逐轮调整。"}</strong><small>{project?.qc?.passed ? "最近一次 QC 已通过" : "等待 QC"}</small></div>
              <button type="button" className="continue-button" disabled={!project?.qc?.passed || busy || project?.status === "chat_editing"} onClick={() => void render()}><Flag size={17} /> 导出当前版本正式成片</button>
            </section>
            <section className="chat-panel" aria-label="视频编辑对话">
              <div className="chat-heading"><div><p className="eyebrow">EDIT SESSION</p><h3>和 Claude Code 继续聊</h3></div><span className="chat-base-badge">本轮基于 v{latestVersion}</span></div>
              <div className="chat-history" aria-live="polite">{(project?.editSession?.messages || []).length ? project?.editSession?.messages.map((item) => <article className={`chat-message ${item.role === "assistant" ? "assistant" : "user"} ${item.error ? "error" : ""}`} key={item.id}><div className="chat-message-meta"><strong>{item.role === "assistant" ? "Claude Code" : "你"}</strong>{item.version ? <span>v{item.version}</span> : item.timeMs != null ? <span>{ms(item.timeMs)}{item.rangeEndMs != null ? `–${ms(item.rangeEndMs)}` : ""}</span> : null}</div><p>{item.text}</p></article>) : <div className="chat-empty"><MessageSquareText size={20} /><strong>从最新版本开始调整</strong><p>告诉 Claude Code 你想改变的地方，它会读取当前工程、生成新版本并重新审片。</p></div>}{project?.status === "chat_editing" ? <div className="chat-message assistant pending"><div className="chat-message-meta"><strong>Claude Code</strong><span>处理中</span></div><p>{project.editor?.activity?.at(-1)?.message || "正在读取最新版本并生成新的预览……"}</p></div> : null}</div>
              <div className="chat-suggestions"><button type="button" onClick={() => setChatDraft("删掉这一段停顿，其他地方保持不变")}>删掉停顿</button><button type="button" onClick={() => setChatDraft("把字幕做得更大，并保持当前颜色和位置")}>调整字幕</button><button type="button" onClick={() => setChatDraft("在这句话出现时增加一次轻微 punch-in")}>增加推近</button><button type="button" onClick={() => setChatDraft("给这一段增加合适的 B-roll，其他剪辑保持不变")}>增加 B-roll</button></div>
              <div className="chat-context-fields"><label>开始时间（秒）<input type="number" min="0" step="0.1" value={chatTime} onChange={(event) => setChatTime(event.target.value)} placeholder="可选" /></label><label>结束时间（秒）<input type="number" min="0" step="0.1" value={chatRangeEnd} onChange={(event) => setChatRangeEnd(event.target.value)} placeholder="可选" /></label></div>
              <div className="chat-composer"><textarea value={chatDraft} onChange={(event) => setChatDraft(event.target.value)} onKeyDown={(event) => { if ((event.metaKey || event.ctrlKey) && event.key === "Enter") void sendChatMessage(); }} placeholder="例如：00:18–00:24 节奏太慢，删掉停顿，并保持其他地方不变" aria-label="对话修改内容" /><button type="button" className="primary-button" disabled={!chatDraft.trim() || busy || project?.status === "chat_editing"} onClick={() => void sendChatMessage()}><ArrowRight size={17} /> 发送修改</button></div>
              {message && <div className="api-alert"><strong>{message}</strong></div>}
              <small className="chat-footnote">每一轮会生成一个新版本，旧版本保留。按 Ctrl/Cmd + Enter 发送。</small>
            </section>
          </div>
        </>}
      </section><aside className="side-panel"><div className="side-card progress-card"><div className="side-card-heading"><span>本次进度</span><Gauge size={16} /></div><div className="health-ring" style={{ "--progress": `${progress}%` } as React.CSSProperties}><strong>{progress}%</strong><span>{currentIndex + 1} / {stageIds.length}</span></div><div className="progress-state"><strong>{phaseLabel(project?.status)}</strong><span>{estimatedWait(project)}</span></div><p>{workflowStatus(project)}</p>{project?.media && <p className="progress-media">{project.media.filename} · {ms(project.media.durationMs)}</p>}<div className="save-note"><Check size={14} /> 项目会自动保存，刷新后可继续</div></div><details className="service-details"><summary>服务信息</summary><p>AI 剪辑：{config?.editor?.available ? config.editor.model : config?.anthropic ? "已配置" : "未配置"} · 转录服务：{config?.transcription ? "已配置" : "未配置"}</p><p>每一步结果会自动保存，刷新页面后可以继续。</p></details></aside></div>
    </section>
    <footer className="footer"><span>CASE 01 / WAYNE ST LEDGER</span><span>AI 生成草剪 · 人工确认后导出</span><span>真实产物优先</span></footer>
    {showHistory && <div className="modal-backdrop" role="presentation" onClick={() => setShowHistory(false)}><section className="modal-panel history-panel" role="dialog" aria-modal="true" aria-labelledby="history-title" onClick={(event) => event.stopPropagation()}><div className="modal-heading"><div><p className="eyebrow">PROJECT HISTORY</p><h3 id="history-title">项目历史</h3></div><button className="icon-button" type="button" aria-label="关闭项目历史" onClick={() => setShowHistory(false)}>×</button></div>{history.length ? <div className="history-list">{history.map((item) => <button className={`history-item ${item.id === projectId ? "current" : ""}`} type="button" key={item.id} onClick={() => void openHistory(item.id)}><div className="history-item-top"><strong>{item.media?.filename || "未命名项目"}</strong><span className={`history-status history-${item.status}`}>{historyStatus(item)}</span></div><p>{item.goal || "未设置剪辑目标"}</p><small>{relativeDate(item.updatedAt)} · {item.media ? `${ms(item.media.durationMs)} · v${item.latestVersion}` : "尚未上传视频"}</small></button>)}</div> : <div className="empty-state"><FileVideo size={24} /><strong>还没有历史项目</strong><p>上传第一条视频后，项目会自动出现在这里。</p></div>}</section></div>}
    {showHelp && <div className="modal-backdrop" role="presentation" onClick={() => setShowHelp(false)}><section className="modal-panel help-panel" role="dialog" aria-modal="true" aria-labelledby="help-title" onClick={(event) => event.stopPropagation()}><div className="modal-heading"><div><p className="eyebrow">QUICK GUIDE</p><h3 id="help-title">第一次使用？</h3></div><button className="icon-button" type="button" aria-label="关闭帮助" onClick={() => setShowHelp(false)}>×</button></div><div className="help-steps"><div><b>1</b><span><strong>上传口播视频</strong><small>推荐 60–90 秒，MP4 或 MOV。</small></span></div><div><b>2</b><span><strong>等待 AI 草剪</strong><small>转录、剪辑和预览会自动保存。</small></span></div><div><b>3</b><span><strong>播放并批注</strong><small>在时间点写下要修改的地方。</small></span></div><div><b>4</b><span><strong>确认后导出</strong><small>导出后请完整观看成片再发布。</small></span></div></div><p className="help-footnote">如果遇到超时，保留当前页面并点击“从这里继续生成”，不需要重新上传。</p></section></div>}
  </main>;

}
